(* [comment removed for export] *)
Definition a1x (ps : SR.post_spec) : expr := match find (fun ie : nat * expr => Nat.eqb (fst ie) 11) (SR.ps_regs ps) with Some (_, e) => e | None => ELit (-1) end.
